"""Research portability bundle only; no publication or product activation."""
import hashlib,importlib.metadata,json,shutil
from pathlib import Path
from data import ROOT,PARENT,RESULTS,save
from model import ASSETS
from assets import LICENSES

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 stage=RESULTS/'portable-v4';summary=json.loads((stage/'summary.json').read_text(encoding='utf-8'));assert summary['allDevelopmentTextIntervalPaddingAcceptEqual'] and summary['priorSelectedTorchRawReproducedExactly'];selection=json.loads((ROOT/'selection.json').read_text(encoding='utf-8'));selected=selection['selected'];assert sha(selected['path'])==selected['sha256'];out=PARENT/'portable-v4';source=Path(__file__).parent
 if (out/'metadata.json').exists():raise RuntimeError('Bundle cannot overwrite an existing receipt')
 assert shutil.disk_usage(PARENT).free>=1024**3
 assert sha(out/'model.onnx')==summary['onnxSha256'] and sha(out/'dictionary.json')==summary['dictionarySha256']
 assert json.loads((out/'dictionary.json').read_text(encoding='utf-8'))==json.loads(Path('/workspace/scratch/ocr-production-development-20261015-v1/models/ascii-dictionary.json').read_text(encoding='utf-8'))
 for name,path in {'adapter-state.safetensors':Path(selected['path']),'official-config.json':ASSETS/'config.json','official-inference.yml':ASSETS/'inference.yml','foundation-model-card.md':ASSETS/'README.md','model-APACHE-2.0.txt':Path('/usr/share/common-licenses/Apache-2.0'),'adapter.py':source/'adapter.py','model.py':source/'model.py','image_tensor.py':source.parent/'image_tensor.py','training-protocol.json':source/'protocol.json'}.items():shutil.copyfile(path,out/name)
 assert sha(out/'adapter-state.safetensors')==selected['sha256']
 receipts=out/'receipts';receipts.mkdir()
 for name,path in {'registration-freeze.json':ROOT/'registration-freeze.json','training-freeze.json':ROOT/'freeze.json','exclusion-receipt.json':ROOT/'exclusion-receipt.json','newdev-initialization-self-consistency.json':RESULTS/'newdev-initialization-self-consistency.json','selection.json':ROOT/'selection.json','fresh-freeze.json':RESULTS/'fresh-freeze.json','fresh-comparison.json':RESULTS/'fresh-comparison.json','onnx-fidelity.json':stage/'summary.json','font-download-receipt.json':PARENT/'assets/font-download-receipt.json','foundation-download-receipt.json':ASSETS/'download-receipt.json'}.items():shutil.copyfile(path,receipts/name)
 licenses=out/'font-licenses';licenses.mkdir()
 for name,path in LICENSES.items():shutil.copyfile(path,licenses/(name+'-LICENSE.txt'))
 contract={'format':'Standard ONNX opset17; domains empty/ai.onnx only; FP32 original438 softmax; no custom Windows op','inputs':{'x':{'dtype':'float32','shape':'[B,3,48,W]','clientBounds':'B1..2 verified, W320..960, BGR channels'},'valid_width':{'dtype':'int64','shape':'[B]','bounds':'1..inputWidth'}},'outputs':{'probabilities':'float32[B,T,438]','reject_probability':'float32[B], uncalibrated sigmoid'},'dictionary':'dictionary.json: blank0; original official character_dict then final space437, total438; full softmax without ASCII renormalization','preprocess':'Exact reference image_tensor.py tensor(): nonwhite whole-line bbox+2originalpx externally; preserve crop origin/baseline/relative heights/internal gaps; original-pixel center bilinear and uint8 rounding before BGR normalization, pad normalized0; validWidth actual resampled width; minimum320 padded width; source aspect ratios needing inputWidth>960 rejected, never silently stretched','ctc':'greedy argmax, blank removed, adjacent same-class run collapses, piece confidence is maximum class probability across run; native source endpoints based on original inputWidth/T. interval End*inputWidth > validWidth*T is unsupported padding and refused, never clamped. Source offset maps through supplied crop rect.','rejectMask':'(2*t+1)*inputWidth < 2*T*validWidth, integer arithmetic','diagnosticAcceptance':'Nonempty printableASCII, minimum emitted CTC confidence>=.8, reject_probability<=.05, no unsupported CTC interval. These are uncalibrated diagnostics, not permission to auto-adopt or proof of input/source completeness.','safetensors':'adapter-state.safetensors includes official.* and reject.* keys; load strictly through Adapter. It is not an unmodified official HF state dict. Standard ONNX consumers do not need PyTorch/Transformers.','platformLimits':'Linux ORT CPU validation only; no native Windows throughput/full-document qualification or CoreML/iPhone execution. iOS repository untouched. Model publication/active product switch requires separate parent decision.'};save(out/'format-contract.json',contract)
 metadata={'status':'Research-only portable model, inactive/unpublished','activeBaselineOnnxSha256':'9dd3ed77db4f2af171cf434d200c666033c9bdfe5f33446bc47dbfecac90d703','initializerAndTeacherCheckpointSha256':'7313bee5dabf17998010c6f47844fe80649744b03c0366af05c627fc47314547','selectedCheckpointSha256':selected['sha256'],'onnxSha256':summary['onnxSha256'],'dictionarySha256':summary['dictionarySha256'],'dependencies':{n:importlib.metadata.version(n) for n in ['torch','transformers','onnx','onnxruntime','numpy','Pillow','safetensors','fonttools']},'foundationLicense':'PP-OCRv5 official foundation Apache-2.0, pinned provenance in foundation-download-receipt/model card; font OFL/Apache license copies are bundled','iosEdited':False,'coremlAttempted':False,'activated':False,'published':False};save(out/'metadata.json',metadata)
 (out/'README.md').write_text('# PP-OCRv5 ASCII continuation research bundle\n\nStandard FP32 ONNX and full438 dictionary; see format-contract.json. Actual initializer and teacher are active font-balanced epoch4, not unadapted official weights. Training selection and independent fresh evidence are in receipts. Every regression and false acceptance remains material; no activation/publication or iPhone validation is implied.\n\nFor Torch reproduction place adapter.py/model.py together, point model.ASSETS at the pinned official architecture assets, create Adapter().eval(), and strictly load adapter-state.safetensors. Standard ONNX needs x plus int64 valid_width. Source cropping, provenance and required image confirmation remain consumer responsibilities.\n',encoding='utf-8',newline='\n')
 files={str(p.relative_to(out)):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in out.rglob('*') if p.is_file()};receipt={'root':str(out),'files':files,'totalBytes':sum(x['bytes'] for x in files.values()),'fileCount':len(files),'allFilesVerified':True,'iosEdited':False,'activated':False,'published':False};save(stage/'package-receipt.json',receipt);print(json.dumps({k:v for k,v in receipt.items() if k!='files'}))
